impl<T: gx::Real> Motor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[0].mul_add(x[0], t1);
        t2
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (12 mul, 3 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Motor<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t3 = t0 * t1;
        let t4 = t1 * t1;
        let t5 = t0.mul_add(t0, t4);
        let t7 = t3.mul_add(T::from_i64(2), t5);
        let t8 = t7.recip();
        let t10 = t1 * t8;
        let t11 = t0.mul_add(t8, t10);
        let t12 = x[0] * t11;
        let t13 = x[1] * t11;
        let t14 = x[2] * t11;
        let t15 = x[3] * t11;
        let t16 = -t13;
        let t17 = -t14;
        let t18 = -t15;
        Motor::from_coeffs([t12, t16, t17, t18])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p2 = x[0].mul_add(x[0], p1);
        let s0 = (p2).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Motor::from_coeffs([t0, t1, t2, t3]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline(always)]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Motor::from_coeffs(c).normalized()
    }

}

impl<T: gx::Real> gx::Log<Point<(), T>> for gx::Unit<Motor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Point<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p0 = x[1] * x[1];
        let p1 = -p0;
        let [h0, h1] = gx::study::log_coeffs_rotation((x[0], T::from_i64(0)), (p1, T::from_i64(0)));
        let t0 = x[2] * h0;
        let t1 = x[3] * h0;
        let t2 = x[1] * h0;
        Point::from_coeffs([t0, t1, t2])
        })
    }
}

#[doc = "An improper rigid motion (a glide reflection): the odd subalgebra."]
///
/// Blades, in coefficient order: `[e1, e2, e0, e012]`.
///
/// `S` lists the open slots: `Flector` (that is, `Flector<()>`) is a value, `Flector<(A,)>` a
/// linear map from `A`, `Flector<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Flector<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 4],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Flector<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Flector<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Flector<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Flector<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Flector");
        for (b, c) in <Flector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Flector {
    const N: usize = 4;
    const NAME: &'static str = "Flector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1", "e2", "e0", "e012"];
    type Arr<X: gx::Elem> = [X; 4];
    type Mv<S: gx::Slots, T: gx::Coef> = Flector<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 4] {
        [f(0), f(1), f(2), f(3)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 4], mut f: impl FnMut(&X) -> Y) -> [Y; 4] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 4],
        b: &[Y; 4],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 4] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3])]
    }
}

