impl<T: gx::Real> Flector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[0].mul_add(x[0], t1);
        t2
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (12 mul, 3 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Flector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t3 = t0 * t1;
        let t4 = t1 * t1;
        let t5 = t0.mul_add(t0, t4);
        let t7 = t3.mul_add(T::from_i64(2), t5);
        let t8 = t7.recip();
        let t10 = t1 * t8;
        let t11 = t0.mul_add(t8, t10);
        let t12 = x[0] * t11;
        let t13 = x[1] * t11;
        let t14 = x[2] * t11;
        let t15 = x[3] * t11;
        let t16 = -t15;
        Flector::from_coeffs([t12, t13, t14, t16])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p2 = x[0].mul_add(x[0], p1);
        let s0 = (p2).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Flector::from_coeffs([t0, t1, t2, t3]))
    }

}

#[doc = "A general multivector, in the bivector.net order."]
///
/// Blades, in coefficient order: `[1, e0, e1, e2, e01, e20, e12, e012]`.
///
/// `S` lists the open slots: `Multivector` (that is, `Multivector<()>`) is a value, `Multivector<(A,)>` a
/// linear map from `A`, `Multivector<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Multivector<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 8],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Multivector<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Multivector<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Multivector<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Multivector<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Multivector");
        for (b, c) in <Multivector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Multivector {
    const N: usize = 8;
    const NAME: &'static str = "Multivector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["1", "e0", "e1", "e2", "e01", "e20", "e12", "e012"];
    type Arr<X: gx::Elem> = [X; 8];
    type Mv<S: gx::Slots, T: gx::Coef> = Multivector<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(mut f: impl FnMut(usize) -> X) -> [X; 8] {
        [f(0), f(1), f(2), f(3), f(4), f(5), f(6), f(7)]
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 8], mut f: impl FnMut(&X) -> Y) -> [Y; 8] {
        [f(&a[0]), f(&a[1]), f(&a[2]), f(&a[3]), f(&a[4]), f(&a[5]), f(&a[6]), f(&a[7])]
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 8],
        b: &[Y; 8],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 8] {
        [f(&a[0], &b[0]), f(&a[1], &b[1]), f(&a[2], &b[2]), f(&a[3], &b[3]), f(&a[4], &b[4]), f(&a[5], &b[5]), f(&a[6], &b[6]), f(&a[7], &b[7])]
    }
}

