impl<S: gx::Slots, T: gx::Coef> gx::Transform<Line<S, T>> for Line<(), T> {
    type Output = Line<S, T>;
    #[inline(always)]
    fn transform(self, x: Line<S, T>) -> Line<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 3>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = v[0] * v[1];
        let t3 = v[0] * v[2];
        let t4 = v[1] * v[2];
        let t5 = t0 - t1;
        let t6 = t0 + t1;
        let t8 = xv[1] * t2;
        let t9 = xv[0] * t2;
        let t12 = xv[1] * t4;
        let t14 = t8 * T::from_i64(2);
        let t15 = xv[0].mul_add(t5, t14);
        let t16 = t9 * T::from_i64(2);
        let t17 = (-xv[1]).mul_add(t5, t16);
        let t18 = xv[0].mul_add(t3, t12);
        let t19 = t18 * T::from_i64(2);
        let t20 = (-xv[2]).mul_add(t6, t19);
            return Line { c: gx::slots::from_values::<S, T, 3>([t15, t17, t20]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[0] * v[1];
        let m3 = v[0] * v[2];
        let m4 = v[1] * v[2];
        let m5 = m0 - m1;
        let m6 = m2 * T::from_i64(2);
        let m7 = -m5;
        let m8 = m3 * T::from_i64(2);
        let m9 = m4 * T::from_i64(2);
        let m10 = m0 + m1;
        let m11 = -m10;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Line { c: [(x[0].scale(m5) + x[1].scale(m6)).0, (x[0].scale(m6) + x[1].scale(m7)).0, (x[0].scale(m8) + x[1].scale(m9) + x[2].scale(m11)).0] }
    }
}

