        let m3 = v[0] * v[2];
        let m4 = v[1] * v[2];
        let m5 = m0 - m1;
        let m6 = m2 * T::from_i64(2);
        let m7 = -m5;
        let m8 = m3 * T::from_i64(2);
        let m9 = m4 * T::from_i64(2);
        let m10 = m0 + m1;
        let m11 = -m10;
