impl<S: gx::Slots, T: gx::Coef> gx::Transform<Rotor<S, T>> for Line<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Rotor<S, T>) -> Motor<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 2>(&x.c) {
        let t1 = v[1] * v[1];
        let t2 = v[0].mul_add(v[0], t1);
        let t3 = v[2] * xv[1];
        let t4 = xv[0] * t2;
        let t5 = xv[1] * t2;
        let t6 = v[0] * t3;
        let t7 = v[1] * t3;
        let t8 = -t5;
        let t9 = t6 * T::from_i64(2);
        let t10 = t7 * T::from_i64(2);
            return Motor { c: gx::slots::from_values::<S, T, 4>([t4, t8, t9, t10]) };
        }
        let m1 = v[1] * v[1];
        let m2 = v[0] * v[2];
        let m3 = v[1] * v[2];
        let m4 = v[0].mul_add(v[0], m1);
        let m5 = -m4;
        let m6 = m2 * T::from_i64(2);
        let m7 = m3 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m4)).0, (x[1].scale(m5)).0, (x[1].scale(m6)).0, (x[1].scale(m7)).0] }
    }
}

