impl<S: gx::Slots, T: gx::Coef> gx::Transform<Motor<S, T>> for Point<(), T> {
    type Output = Motor<S, T>;
    #[inline(always)]
    fn transform(self, x: Motor<S, T>) -> Motor<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 4>(&x.c) {
        let t0 = v[2] * v[2];
        let t1 = v[2] * xv[1];
        let t2 = xv[0] * t0;
        let t3 = xv[1] * t0;
        let t4 = v[0] * t1;
        let t6 = v[1] * t1;
        let t8 = t4 * T::from_i64(2);
        let t9 = (-xv[2]).mul_add(t0, t8);
        let t10 = t6 * T::from_i64(2);
        let t11 = (-xv[3]).mul_add(t0, t10);
            return Motor { c: gx::slots::from_values::<S, T, 4>([t2, t3, t9, t11]) };
        }
        let m0 = v[2] * v[2];
        let m1 = v[0] * v[2];
        let m2 = v[1] * v[2];
        let m3 = m1 * T::from_i64(2);
        let m4 = -m0;
        let m5 = m2 * T::from_i64(2);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Motor { c: [(x[0].scale(m0)).0, (x[1].scale(m0)).0, (x[1].scale(m3) + x[2].scale(m4)).0, (x[1].scale(m5) + x[3].scale(m4)).0] }
    }
}

