        let t8 = xv[3] * t2;
        let t9 = xv[2] * t2;
        let t10 = xv[3] * t4;
        let t11 = t8 * T::from_i64(2);
        let t12 = xv[2].mul_add(t4, t11);
        let t14 = (-t9).mul_add(T::from_i64(2), t10);
