        let t1 = v[0] * xv[1];
        let t2 = xv[0] * t0;
        let t3 = xv[1] * t0;
        let t4 = xv[2] * t0;
        let t5 = v[2] * t1;
        let t7 = v[1] * t1;
        let t9 = (-t5).mul_add(T::from_i64(2), t4);
        let t10 = t7 * T::from_i64(2);
        let t11 = xv[3].mul_add(t0, t10);
            return Motor { c: gx::slots::from_values::<S, T, 4>([t2, t3, t9, t11]) };
